]
RCON = [0x00,0x01,0x02,0x04,0x08,0x10,0x20,0x40,0x80,0x1B,0x36]

def _xtime(a):
    return ((a << 1) & 0xff) ^ (0x1b if (a & 0x80) else 0)

def _mul(a, b):
    res = 0
    while b:
        if b & 1:
            res ^= a
        a = _xtime(a)
        b >>= 1
    return res

def _expand_key(key):
    assert len(key) == 16
    words = [list(key[i:i+4]) for i in range(0, 16, 4)]
    for i in range(4, 44):
        temp = words[i - 1][:]
        if i % 4 == 0:
            temp = temp[1:] + temp[:1]
            temp = [SBOX[x] for x in temp]
            temp[0] ^= RCON[i // 4]
        words.append([words[i - 4][j] ^ temp[j] for j in range(4)])
    round_keys = []
    for r in range(11):
        rk = []
        for w in words[4*r:4*r+4]:
            rk += w
        round_keys.append(rk)
    return round_keys

def _add_round_key(s, rk):
    for i in range(16):
        s[i] ^= rk[i]

def _sub_bytes(s):
    for i in range(16):
        s[i] = SBOX[s[i]]

def _shift_rows(s):
    # state is column-major: index = row + 4*column
    s[1], s[5], s[9], s[13] = s[5], s[9], s[13], s[1]
    s[2], s[6], s[10], s[14] = s[10], s[14], s[2], s[6]
    s[3], s[7], s[11], s[15] = s[15], s[3], s[7], s[11]

def _mix_columns(s):
    for c in range(4):
        i = 4*c
        a0,a1,a2,a3 = s[i],s[i+1],s[i+2],s[i+3]
        s[i]   = _mul(a0,2) ^ _mul(a1,3) ^ a2 ^ a3
        s[i+1] = a0 ^ _mul(a1,2) ^ _mul(a2,3) ^ a3
        s[i+2] = a0 ^ a1 ^ _mul(a2,2) ^ _mul(a3,3)
        s[i+3] = _mul(a0,3) ^ a1 ^ a2 ^ _mul(a3,2)

def aes128_encrypt_block(block, key):
    if len(block) != 16 or len(key) != 16:
        raise ValueError("AES block/key size error")
    s = list(block)
    keys = _expand_key(key)
    _add_round_key(s, keys[0])
    for r in range(1, 10):
        _sub_bytes(s); _shift_rows(s); _mix_columns(s); _add_round_key(s, keys[r])
    _sub_bytes(s); _shift_rows(s); _add_round_key(s, keys[10])
    return bytes(s)

def evp_key_iv(password):
    p = password.encode("utf-8")
    d1 = hashlib.md5(p).digest()
    d2 = hashlib.md5(d1 + p).digest()
    return d1, d2

def aes_cfb_crypt(data, password, encrypt=True):
    key, iv = evp_key_iv(password)
    prev = iv
    out = bytearray()
    for i in range(0, len(data), 16):
        chunk = data[i:i+16]
        stream = aes128_encrypt_block(prev, key)
        c = bytes([chunk[j] ^ stream[j] for j in range(len(chunk))])
        out += c
        # OpenSSL/Crypto++ CFB-128 feedback: ciphertext is the next feedback block.
        prev = c if encrypt else chunk
    return bytes(out)

# Utilities ----------------------------------------------------------------
class AppError(Exception):
    pass

class ParseError(AppError):
    pass

def home_dir():
    return os.environ.get("HOME", str(Path.home()))

def default_config_path():
    return os.path.join(home_dir(), ".caps-log", "config.ini")

def expand_path(p):
    if p is None:
        return p
    if p == "~":
        return home_dir()
    if p.startswith("~/"):
        return os.path.join(home_dir(), p[2:])
    return p

def error_exit(msg):
    sys.stderr.write("Captain's log encountered an error: \n " + str(msg) + "\n")
    return 1

OPTIONS = {
    "help": ("help", False),
    "config": ("config", True),
    "log-dir-path": ("log-dir-path", True),
    "log-name-format": ("log-name-format", True),
    "sunday-start": ("sunday-start", False),
    "first-line-section": ("first-line-section", False),
    "password": ("password", True),
    "encrypt": ("encrypt", False),
    "decrypt": ("decrypt", False),
}
SHORT = {"h": "help", "c": "config"}

def _ambiguous_message(given, matches):
    names = ["--" + m for m in matches]
    if len(names) == 2:
        tail = names[0] + "', and '" + names[1]
        return f"option '--{given}' is ambiguous and matches '{tail}'"
    return f"option '--{given}' is ambiguous"

def resolve_long(name):
    if name in OPTIONS:
        return name
    matches = [k for k in OPTIONS if k.startswith(name)]
    if len(matches) == 1:
        return matches[0]
    if len(matches) > 1:
        raise ParseError(_ambiguous_message(name, matches))
    raise ParseError(f"unrecognised option '--{name}'")

def set_option(opts, canonical, value=True):
    if canonical in opts:
        raise ParseError(f"option '--{canonical}' cannot be specified more than once")
    opts[canonical] = value

def parse_argv(argv):
    opts = {}
    positionals = []
    i = 0
    while i < len(argv):
        tok = argv[i]
        if tok == "--":
            positionals.extend(argv[i+1:]); break
        if tok.startswith("--") and tok != "--":
            body = tok[2:]
            if "=" in body:
                name, val = body.split("=", 1)
                canon = resolve_long(name)
                takes = OPTIONS[canon][1]
                if not takes:
                    raise ParseError(f"option '--{canon}' does not take any arguments")
                set_option(opts, canon, val)
            else:
                canon = resolve_long(body)
                takes = OPTIONS[canon][1]
                if takes:
                    if i + 1 >= len(argv):
                        raise ParseError(f"the required argument for option '--{canon}' is missing")
                    i += 1
                    set_option(opts, canon, argv[i])
                else:
                    set_option(opts, canon, True)
        elif tok.startswith("-") and tok != "-":
            body = tok[1:]
            # Boost accepts combinations of known short options. If an unknown appears
            # in a combined token, the whole token is reported.
            if any(ch not in SHORT for ch in body):
                raise ParseError(f"unrecognised option '-{body}'")
            j = 0
            while j < len(body):
                canon = SHORT[body[j]]
                takes = OPTIONS[canon][1]
                if takes:
                    if j + 1 < len(body):
                        val = body[j+1:]
                        set_option(opts, canon, val)
                        j = len(body)
                    else:
                        if i + 1 >= len(argv):
                            raise ParseError(f"the required argument for option '--{canon}' is missing")
                        # A close quirk of boost::program_options: '-c -h' reports
                        # missing because -h is a recognized short option.
                        if argv[i+1] == "-h":
                            raise ParseError(f"the required argument for option '--{canon}' is missing")
                        i += 1
                        set_option(opts, canon, argv[i])
                        j = len(body)
                else:
                    set_option(opts, canon, True)
                    j += 1
        else:
            positionals.append(tok)
        i += 1
    return opts, positionals

def print_help():
