# Config -------------------------------------------------------------------
def parse_ini(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            lines = f.readlines()
    except FileNotFoundError:
        raise AppError(f"Failed to open file: {path}")
    except IsADirectoryError:
        raise AppError("basic_filebuf::underflow error reading the file: Is a directory")
    except OSError as e:
        raise AppError(f"Failed to open file: {path}")
    data = {}
    seen = {}
    section = ""
    for lineno, raw in enumerate(lines, 1):
        line = raw.rstrip("\n\r")
        stripped = line.strip()
        if not stripped or stripped.startswith("#") or stripped.startswith(";"):
            continue
        if stripped.startswith("["):
            if "]" not in stripped:
                raise AppError(f"Failed to parse configuration file: <unspecified file>({lineno}): unmatched '['")
            if not stripped.endswith("]"):
                # property_tree is permissive in some cases, but this is a sane close match.
                section = stripped[1:stripped.index("]")].strip()
            else:
                section = stripped[1:-1].strip()
            seen.setdefault(section, set())
            continue
        if "=" not in stripped:
            raise AppError(f"Failed to parse configuration file: <unspecified file>({lineno}): '=' character not found in line")
        key, val = stripped.split("=", 1)
        key = key.strip(); val = val.strip()
        sec_seen = seen.setdefault(section, set())
        if key in sec_seen:
            raise AppError(f"Failed to parse configuration file: <unspecified file>({lineno}): duplicate key name")
        sec_seen.add(key)
        full = f"{section}.{key}" if section else key
        data[full] = val
    return data

def truthy(v):
    return str(v).strip().lower() in ("true", "1")

def build_config(cli):
    cfg_path = expand_path(cli.get("config", default_config_path()))
    data = parse_ini(cfg_path)
    cfg = {
        "config": cfg_path,
        "log_dir": expand_path(data.get("log-dir-path", os.path.join(home_dir(), ".caps-log", "day"))),
        "log_format": data.get("log-filename-format", DEFAULT_LOG_FORMAT),
        "sunday_start": truthy(data.get("sunday-start", "false")),
        "first_line_section": truthy(data.get("first-line-section", "false")),
        "password": data.get("password", ""),
        "git_enable": truthy(data.get("git.enable-git-log-repo", "false")),
        "git_ssh_key": expand_path(data.get("git.ssh-key-path", "")),
        "git_ssh_pub_key": expand_path(data.get("git.ssh-pub-key-path", "")),
        "git_repo_root": expand_path(data.get("git.repo-root", "")),
        "git_remote": data.get("git.remote-name", "origin"),
        "git_branch": data.get("git.main-branch-name", "master"),
        "events": parse_events(data),
    }
    if "log-dir-path" in cli:
        cfg["log_dir"] = expand_path(cli["log-dir-path"])
    if "log-name-format" in cli:
        cfg["log_format"] = cli["log-name-format"]
    if "sunday-start" in cli:
        cfg["sunday_start"] = True
    if "first-line-section" in cli:
        cfg["first_line_section"] = True
    if "password" in cli:
        cfg["password"] = cli["password"]
    return cfg

def parse_events(data):
    events = []
    for full, val in data.items():
        if not full.startswith("calendar-events.") or not full.endswith(".name"):
            continue
        base = full[:-5]
        name = val
        date_s = data.get(base + ".date", "")
        parts = [p for p in date_s.strip().split(".") if p != ""]
        if len(parts) >= 2:
            try:
                day = int(parts[0]); month = int(parts[1])
                group = base.split(".")[1] if len(base.split(".")) > 1 else "events"
                events.append({"group": group, "name": name, "day": day, "month": month})
            except Exception:
                pass
    return events

# Log parsing ---------------------------------------------------------------
def year_dir(log_dir, year):
    return Path(log_dir) / f"y{year:04d}"

def log_path_for_date(cfg, day):
    return year_dir(cfg["log_dir"], day.year) / day.strftime(cfg["log_format"])

def template_for_date(day):
    return f"# {day.day:02d}. {day.month:02d}. {day.year % 100:02d}."

def format_to_regex(fmt):
    res = ""
    groups = []
    i = 0
    while i < len(fmt):
        ch = fmt[i]
        if ch == "%" and i + 1 < len(fmt):
            code = fmt[i+1]
            if code == "Y":
                res += r"(?P<Y>\d{4})"; groups.append("Y")
            elif code == "y":
                res += r"(?P<y>\d{2})"; groups.append("y")
            elif code == "m":
                res += r"(?P<m>\d{1,2})"; groups.append("m")
            elif code == "d":
                res += r"(?P<d>\d{1,2})"; groups.append("d")
            else:
                res += re.escape("%" + code)
            i += 2
        else:
            res += re.escape(ch); i += 1
    return re.compile("^" + res + "$"), groups

def parse_date_from_name(name, fmt, view_year):
    rx, _ = format_to_regex(fmt)
    m = rx.match(name)
    if not m:
        return None
    try:
        gd = m.groupdict()
        if gd.get("Y"):
            year = int(gd["Y"])
        elif gd.get("y"):
            yy = int(gd["y"])
            year = 2000 + yy if yy < 69 else 1900 + yy
        else:
            year = view_year
        month = int(gd.get("m") or 1)
        day = int(gd.get("d") or 1)
        d = _dt.date(year, month, day)
        if d.year != view_year:
            return None
        return d
    except Exception:
        return None

def recognized_logs(cfg, year, encrypted_locked=False):
    if encrypted_locked:
        return {}
    yd = year_dir(cfg["log_dir"], year)
    logs = {}
    if not yd.is_dir():
        return logs
    for p in sorted(yd.iterdir()):
        if not p.is_file():
            continue
        d = parse_date_from_name(p.name, cfg["log_format"], year)
        if d:
            logs[d] = p
    return logs

def normalize_section(s):
    return s.strip().lower()

def normalize_tag(s):
    s = s.strip()
    # Body/extra information begins at the first ':' or '('.
    cut = len(s)
    for mark in (":", "("):
        pos = s.find(mark)
        if pos != -1:
            cut = min(cut, pos)
    return s[:cut].strip().lower()

def parse_log_text(text, first_line_section=False):
    sections = set()
    tags = set()
    section_tags = {}
    current = "<root section>"
    lines = text.splitlines()
    for idx, line in enumerate(lines):
        stripped_left = line.lstrip()
        if line.startswith("# "):
            if idx == 0 and not first_line_section:
                current = "<root section>"
            else:
                current = normalize_section(line[2:])
                if current:
                    sections.add(current)
            continue
        if stripped_left.startswith("*"):
            rest = stripped_left[1:].strip()
            if not rest:
                continue
            tag = normalize_tag(rest)
            if tag:
                tags.add(tag)
                section_tags.setdefault(current, set()).add(tag)
                if current == "<root section>":
                    sections.add(current)
    return sections, tags, section_tags

def summarize_logs(cfg, logs):
    section_dates = {}
    tag_dates = {}
    section_tag_dates = {}
    for d, p in logs.items():
        try:
            text = p.read_text(encoding="utf-8", errors="replace")
        except Exception:
            continue
        sections, tags, st = parse_log_text(text, cfg.get("first_line_section", False))
        for s in sections:
            section_dates.setdefault(s, set()).add(d)
        for t in tags:
            tag_dates.setdefault(t, set()).add(d)
        for s, ts in st.items():
            for t in ts:
                section_tag_dates.setdefault((s, t), set()).add(d)
    return section_dates, tag_dates, section_tag_dates

# Crypto commands -----------------------------------------------------------
def iter_crypto_files(log_dir):
    root = Path(log_dir)
    # Match std::filesystem::directory_iterator behavior: fail if root absent.
    if not root.exists():
        raise AppError(f"filesystem error: directory iterator cannot open directory: No such file or directory [{log_dir}]")
    for child in sorted(root.iterdir(), key=lambda p: p.name):
        if child.is_dir():
            for f in sorted(child.iterdir(), key=lambda p: p.name):
                if f.is_file():
                    yield f

def marker_path(log_dir):
    return Path(log_dir) / ".cle"

def repo_encrypted(log_dir):
    return marker_path(log_dir).is_file()

def encrypt_repo(cfg):
    pw = cfg.get("password", "")
    if not pw:
        raise AppError("Password must be provided when encrypting logs!")
    sys.stdout.write("Applying crypto...\n")
    sys.stdout.flush()
    if repo_encrypted(cfg["log_dir"]):
        raise AppError("Already applied")
    files = list(iter_crypto_files(cfg["log_dir"]))
    for p in files:
        p.write_bytes(aes_cfb_crypt(p.read_bytes(), pw, True))
    marker_path(cfg["log_dir"]).write_bytes(aes_cfb_crypt(MARKER_TEXT, pw, True))

def decrypt_repo(cfg):
    pw = cfg.get("password", "")
    if not pw:
        raise AppError("Password must be provided when decrypting logs!")
    sys.stdout.write("Applying crypto...\n")
    sys.stdout.flush()
    if not repo_encrypted(cfg["log_dir"]):
        raise AppError("Already applied")
    files = list(iter_crypto_files(cfg["log_dir"]))
    for p in files:
        p.write_bytes(aes_cfb_crypt(p.read_bytes(), pw, False))
    try:
        marker_path(cfg["log_dir"]).unlink()
    except FileNotFoundError:
        pass

def validate_encrypted_password(cfg):
    mp = marker_path(cfg["log_dir"])
    try:
        dec = aes_cfb_crypt(mp.read_bytes(), cfg.get("password", ""), False)
    except Exception:
        dec = b""
    if dec != MARKER_TEXT:
        raise AppError("Invalid password provided!")

def decrypt_for_session(cfg):
    files = list(iter_crypto_files(cfg["log_dir"]))
    for p in files:
        p.write_bytes(aes_cfb_crypt(p.read_bytes(), cfg["password"], False))

def encrypt_after_session(cfg):
    files = list(iter_crypto_files(cfg["log_dir"]))
    for p in files:
        p.write_bytes(aes_cfb_crypt(p.read_bytes(), cfg["password"], True))

# Git validation ------------------------------------------------------------
def validate_git(cfg):
    if not cfg.get("git_enable"):
        return
    if not cfg.get("git_ssh_key"):
        raise AppError("SSH key path can not be empty!")
    if not cfg.get("git_ssh_pub_key"):
        raise AppError("SSH public key path can not be empty!")
    if not cfg.get("git_repo_root"):
        raise AppError("Git repository root can not be empty!")
    repo = os.path.abspath(cfg["git_repo_root"])
    logd = os.path.abspath(cfg["log_dir"])
    try:
        common = os.path.commonpath([repo, logd])
    except Exception:
        common = ""
    if common != repo:
        raise AppError(f"Error! Git repo root ({cfg['git_repo_root']}) is not parent of log dir ({cfg['log_dir']})!")
    if not (Path(repo) / ".git").exists():
        raise AppError(f"Git error @/workspace/source/utils/git_repo.cpp:95\n\tcould not find repository from '{cfg['git_repo_root']}'")

# TUI-ish rendering ---------------------------------------------------------
def days_until_event(today, ev):
    try:
        cur = _dt.date(today.year, ev["month"], ev["day"])
    except Exception:
        return None, None
    delta = (cur - today).days
    if delta < 0:
        try:
            nxt = _dt.date(today.year + 1, ev["month"], ev["day"])
            delta = (nxt - today).days
        except Exception:
            return cur, None
    return cur, delta

def todays_events(today, events):
    return [e for e in events if e.get("day") == today.day and e.get("month") == today.month]

def format_header(today, count, year, events):
    evs = todays_events(today, events)
    if evs:
        ev = evs[0]
        prefix = f"Today is: {today.day:02d}. {today.month:02d}. {today.year:04d}. {ev['group']} - {ev['name']}"
    else:
        prefix = f"Today is: {today.day:02d}. {today.month:02d}. {today.year:04d}."
    s = f"{prefix}  | There are {count} log entries for year {year}."
    if len(s) < 80 and not evs:
        pad = (80 - len(s)) // 2
        s = " " * pad + s + " " * (80 - len(s) - pad)
    return s

def month_lines(year, month, sunday_start=False, width=21):
    cal = calendar.Calendar(firstweekday=6 if sunday_start else 0)
    title = calendar.month_name[month]
    wdays = " S  M  T  W  T  F  S " if sunday_start else " M  T  W  T  F  S  S "
    out = [f"╭{title}" + "─" * max(0, width - len(title) - 1) + "╮",
           "│" + wdays[:width].ljust(width) + "│"]
    for week in cal.monthdayscalendar(year, month):
        parts = []
        for d in week:
            parts.append("  " if d == 0 else f"{d:2d}")
        line = " ".join(parts)
        out.append("│" + line[:width].ljust(width) + "│")
    while len(out) < 8:
        out.append("│" + " " * width + "│")
    out.append("╰" + "─" * width + "╯")
    return out

def menu_lines(title, items, width, height, include_select=True):
    inner = width - 2
    out = ["╭" + title + "─" * max(0, inner - len(title)) + "╮"]
    if include_select:
        out.append("│" + "> <select none>".ljust(inner) + "│")
    for name, count in items:
        if len(out) >= height - 1:
            break
        text = f"{count:5d} │ {name}"
        out.append("│" + text[:inner].ljust(inner) + "│")
    while len(out) < height - 1:
        out.append("│" + " " * inner + "│")
    out.append("╰" + "─" * inner + "╯")
    return out

def render_screen(cfg, year, encrypted_locked=False):
    today = _dt.date.today()
    logs = recognized_logs(cfg, year, encrypted_locked)
    section_dates, tag_dates, _ = summarize_logs(cfg, logs) if not encrypted_locked else ({},{},{})
    sections = sorted((name, len(ds)) for name, ds in section_dates.items())
    tags = sorted((name, len(ds)) for name, ds in tag_dates.items())
    include_select = not encrypted_locked
    lines = []
    # A few terminal-control bytes mimic ftxui enough for captures.
    sys.stdout.write("\x00\x1bP$q q\x1b\\\x1b[?1049h\x1b[?7l\x1b[?1000h\x1b[?1003h\x1b[?1015h\x1b[?1006h\x00\r")
    lines.append(format_header(today, len(logs), year, cfg.get("events", [])))
    sec = menu_lines("Sections", sections, 21, 18, include_select)
    tag = menu_lines("Tags", tags, 20, 18, include_select)
    # Right side: compact month blocks, close to the captured 80-column output.
    jan = month_lines(year, 1, cfg.get("sunday_start", False), 21)
    feb = month_lines(year, 2, cfg.get("sunday_start", False), 12)
    may = month_lines(year, today.month, cfg.get("sunday_start", False), 21)
    jun = month_lines(year, min(12, today.month + 1), cfg.get("sunday_start", False), 12)
    right = []
    right.append("╭" + str(year) + "" + "─" * 18 + "┬┬" + "─" * 12 + "╮")
    for i in range(1, min(len(jan), len(feb)) - 1):
        right.append("│" + jan[i][1:-1] + "││" + feb[i][1:-1] + "│")
    right.append("╰" + "─" * 21 + "╯╰" + "─" * 12 + "┤")
    for i in range(len(may)):
        if i < len(jun):
            sep = "╭" if i == 0 else "│"
            right.append(may[i] + jun[i])
    maxh = max(len(sec), len(tag), len(right))
    for i in range(maxh):
        a = sec[i] if i < len(sec) else " " * 21
        b = tag[i] if i < len(tag) else " " * 20
        c = right[i] if i < len(right) else ""
        lines.append(a + b + c)
    # Recent events if any in window.
    event_lines = recent_event_lines(today, cfg.get("events", []))
    lines.extend(event_lines)
    # Preview.
    lines.extend(preview_lines(cfg, today, logs, encrypted_locked))
    sys.stdout.write("\x1b[2K" + "\r\n".join(lines) + "\r\n")
    sys.stdout.flush()

def recent_event_lines(today, events):
    window = 60
    chosen = []
    for ev in events:
        date, delta = days_until_event(today, ev)
        if delta is not None and 0 < delta <= window:
            chosen.append((delta, ev))
    if not chosen:
        return []
    chosen.sort(key=lambda x: x[0])
    out = ["╭Recent & upcoming events (%d)───────────╮" % len(chosen)]
    last_group = None
    for delta, ev in chosen[:4]:
        if ev["group"] != last_group:
            out.append("│" + ev["group"].ljust(38) + "│")
            last_group = ev["group"]
        text = f" - {ev['name']} {ev['month']:02d}.{ev['day']:02d}. (in {delta} days)"
        out.append("│" + text[:38].ljust(38) + "│")
    out.append("╰" + "─" * 39 + "╯")
    return out

def preview_lines(cfg, day, logs, encrypted_locked):
    width = 78
    out = ["╭" + "─" * width + "╮"]
    evs = todays_events(day, cfg.get("events", []))
    title = f"log preview for {day.day:02d}. {day.month:02d}. {day.year%100:02d}."
    if evs:
        groups = {}
        for e in evs:
            groups.setdefault(e["group"], []).append(e["name"])
        extra = " - " + "; ".join(f"{g}: {', '.join(ns)}" for g, ns in groups.items())
        title += extra
    out.append("│" + title.center(width)[:width] + "│")
    if not encrypted_locked and day in logs:
        try:
            preview = logs[day].read_text(encoding="utf-8", errors="replace").splitlines()[:2]
        except Exception:
            preview = []
        for line in preview:
            out.append("│" + line[:width].ljust(width) + "│")
    while len(out) < 4:
        out.append("│" + " " * width + "│")
    out.append("╰" + "─" * width + "╯")
    return out

def restore_terminal():
    sys.stdout.write("\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1000l\x1b[?7h\x1b[?1049l\x1b[?25h\x1b[1 q\x00\r\n")
    sys.stdout.flush()

def ensure_tui_dirs(cfg):
    Path(cfg["log_dir"]).mkdir(parents=True, exist_ok=True)
    (Path(cfg["log_dir"]) / "scratchpads").mkdir(parents=True, exist_ok=True)

def open_editor_for_date(cfg, day):
    editor = os.environ.get("EDITOR", "")
    if not editor:
        return
    p = log_path_for_date(cfg, day)
    existed = p.exists()
    original = None
    if existed:
        try:
            original = p.read_bytes()
        except Exception:
            original = b""
    else:
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(template_for_date(day), encoding="utf-8")
        original = p.read_bytes()
    # The original goes through the shell, so invalid editors print sh errors.
    cmd = editor + " " + shlex.quote(str(p))
    subprocess.run(cmd, shell=True)
    if not existed:
        try:
            after = p.read_bytes()
            if after == original:
                p.unlink()
                try:
                    p.parent.rmdir()
                except Exception:
                    pass
        except FileNotFoundError:
            pass

def handle_input_and_loop(cfg, encrypted_locked, session_encrypted):
    today = _dt.date.today()
    year = today.year
    render_screen(cfg, year, encrypted_locked)
    focus = 0
    buf = ""
    # Allow piped tests to send startup keystrokes. EOF without q intentionally hangs.
    while True:
        try:
            import select
            r, _, _ = select.select([sys.stdin], [], [], 0.10)
            if r:
                ch = os.read(sys.stdin.fileno(), 1)
                if not ch:
                    time.sleep(3600)
                    continue
                c = ch.decode("latin1", errors="ignore")
                buf += c
                if c in ("q", "\x03"):
                    break
                if c == "\t":
                    focus = (focus + 1) % 3
                elif c in ("\r", "\n"):
                    if focus == 2:
                        open_editor_for_date(cfg, today)
                        render_screen(cfg, year, encrypted_locked)
                elif c == "+":
                    year += 1; render_screen(cfg, year, encrypted_locked)
                elif c == "-":
                    year -= 1; render_screen(cfg, year, encrypted_locked)
                elif c == "s":
                    # Minimal scratchpad mode: ensure dir and continue.
                    (Path(cfg["log_dir"]) / "scratchpads").mkdir(parents=True, exist_ok=True)
                else:
                    pass
            else:
                # Keep process alive like a TUI.
                pass
        except KeyboardInterrupt:
            break
    restore_terminal()

def run_tui(cfg):
    validate_git(cfg)
    encrypted = repo_encrypted(cfg["log_dir"])
    session_encrypted = False
    encrypted_locked = False
    if encrypted:
        if cfg.get("password"):
            validate_encrypted_password(cfg)
            decrypt_for_session(cfg)
            session_encrypted = True
        else:
            encrypted_locked = True
    else:
        if cfg.get("password"):
            raise AppError("Password provided for a non encrypted repository!")
    ensure_tui_dirs(cfg)
    try:
        handle_input_and_loop(cfg, encrypted_locked, session_encrypted)
    finally:
        if session_encrypted:
            try:
                encrypt_after_session(cfg)
            except Exception:
                pass

# Main ----------------------------------------------------------------------
def main(argv):
    try:
        cli, _pos = parse_argv(argv)
        if "help" in cli:
            print_help()
            return 0
        cfg = build_config(cli)
        if "encrypt" in cli:
            encrypt_repo(cfg)
            return 0
        if "decrypt" in cli:
            decrypt_repo(cfg)
            return 0
        run_tui(cfg)
        return 0
    except AppError as e:
        return error_exit(str(e))
    except Exception as e:
        return error_exit(str(e))

if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
